const ts = 1788269400.0;
const d = new Date(ts * 1000);
console.log('=== Target timestamp breakdown ===');
console.log('Timestamp :', ts);
console.log('UTC       :', d.toISOString(), '  (1:30 PM UTC)');
console.log();

// 6:30 PM in various US timezones
const tzs = [
  ['US Eastern (UTC-4, EDT)',  -4],
  ['US Central (UTC-5, CDT)',  -5],
  ['US Mountain (UTC-6, MDT)', -6],
  ['US Pacific (UTC-7, PDT)',  -7],
];

console.log('=== 6:30 PM on 2026-09-01 in various timezones ===');
for (const [name, off] of tzs) {
  // 18:30 local = 18:30 - offset(hours) UTC
  const utcHour = 18 - off;  // subtracting negative offset = adding
  const r = new Date(Date.UTC(2026, 8, 1, utcHour, 30, 0));
  const rts = r.getTime() / 1000;
  console.log(name + ': ' + r.toISOString() + '  ts=' + rts + '  match=' + (rts === ts));
}
